from typing_extensions import TypedDict
from typed_core.validation import validator
from binance.core.endpoint.ws_rpc import WsRpcEndpoint


class UsdMWsBalanceV2(TypedDict):
  """USD-M Futures account balance for one asset."""

  accountAlias: str
  """Unique account alias, generated by the server."""
  asset: str
  """Asset name."""
  balance: str
  """Wallet balance."""
  crossWalletBalance: str
  """Cross wallet balance."""
  crossUnPnl: str
  """Unrealized PnL of cross positions."""
  availableBalance: str
  """Available balance."""
  maxWithdrawAmount: str
  """Maximum transferable/withdrawable amount."""
  marginAvailable: bool
  """Whether the asset can be used as margin in multi-assets mode."""
  updateTime: int
  """Last update time, in milliseconds."""


class BalanceV2(WsRpcEndpoint):
  """Query account balance information, per asset (v2)."""

  async def balance_v2(self, *, validate: bool | None = None) -> list[UsdMWsBalanceV2]:
    """Query account balance information, per asset (v2).

    References:
      - [Official docs](https://developers.binance.com/en/docs/catalog/core-trading-derivatives-trading-usd-s-m-futures/api/ws-api/account#futures-account-balance-v2)
    """
    _Response = list[UsdMWsBalanceV2]
    _validator = validator[_Response](_Response)
    return await self.authed_request(
      'v2/account.balance', validator=_validator, validate=validate
    )
